-- =============================================================================
-- V30: Improve Kofi stock categories — data-only recategorization
-- =============================================================================

SET @mdl_business_id = (SELECT id FROM businesses WHERE code = 'MDL');

-- Remove legacy flat categories from V29
UPDATE products p
JOIN product_categories c ON c.id = p.category_id
SET p.category_id = NULL
WHERE p.business_id = @mdl_business_id
  AND c.code IN ('ACCESSORIES', 'PIPE', 'CABLE', 'MAINSWITCH');

DELETE FROM product_categories
WHERE business_id = @mdl_business_id
  AND code IN ('ACCESSORIES', 'PIPE', 'CABLE', 'MAINSWITCH');

-- Improved retail categories
INSERT INTO product_categories (business_id, parent_id, name, code, description, sort_order) SELECT @mdl_business_id, NULL, 'Lighting & Lamps', 'LIGHTING', 'LED panels, bulbs, tubes, downlights, and fittings', 10;
INSERT INTO product_categories (business_id, parent_id, name, code, description, sort_order) SELECT @mdl_business_id, NULL, 'Switches & Sockets', 'SWITCHES_SOCKETS', 'Switches, sockets, plug tops, and dimmers', 20;
INSERT INTO product_categories (business_id, parent_id, name, code, description, sort_order) SELECT @mdl_business_id, NULL, 'Cables & Wiring', 'CABLES', 'Electrical cable sold by the metre or roll', 30;
INSERT INTO product_categories (business_id, parent_id, name, code, description, sort_order) SELECT @mdl_business_id, NULL, 'Conduit & Trunking', 'CONDUIT_TRUNKING', 'Conduit, trunking, clips, and saddles', 40;
INSERT INTO product_categories (business_id, parent_id, name, code, description, sort_order) SELECT @mdl_business_id, NULL, 'Circuit Protection', 'CIRCUIT_PROTECTION', 'MCBs, mainswitches, contactors, and fuses', 50;
INSERT INTO product_categories (business_id, parent_id, name, code, description, sort_order) SELECT @mdl_business_id, NULL, 'Distribution Boards', 'DISTRIBUTION', 'Consumer units and phase distribution boards', 60;
INSERT INTO product_categories (business_id, parent_id, name, code, description, sort_order) SELECT @mdl_business_id, NULL, 'Fans & Ventilation', 'FANS_VENTILATION', 'Ceiling, wall, and industrial fans', 70;
INSERT INTO product_categories (business_id, parent_id, name, code, description, sort_order) SELECT @mdl_business_id, NULL, 'Tools & Accessories', 'ACCESSORIES', 'Holders, connectors, tape, and general consumables', 80;

